//! Scaffolds a standalone integration test harness in tests/slugrails.rs.

use crate::cli::args::extract_root;
use std::fs;
use std::path::Path;
use std::process::ExitCode;

pub const TEST_HARNESS_TEMPLATE: &str = r#"//! SlugRails Autonomous Architectural Test Harness.
//!
//! Generated by SlugRails with integrated SlugPlan.
//! Run with `cargo test --test slugrails` or standard `cargo test`.

#[test]
fn test_slugrails_architecture_invariants() {
    let manifest_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let arch_file = manifest_dir.join(".planning").join("ARCHITECTURE.md");

    if !arch_file.exists() {
        eprintln!(
            "SlugRails Notice: .planning/ARCHITECTURE.md not found. \
            Run 'slugrails init' or 'slugrails plan' to establish your architecture contract."
        );
        return;
    }

    let catalog = codeguards_mcp::library::ensure_test_library_seeded()
        .expect("Failed to initialize SlugRails test library");
    let contract = codeguards_mcp::contract::load_architecture(manifest_dir)
        .expect("Failed to load .planning/ARCHITECTURE.md");
    let files = codeguards_mcp::analyzer::collect_source_files(manifest_dir);
    let exceptions = codeguards_mcp::storage::ProjectExceptions::load(manifest_dir)
        .unwrap_or_default();

    let report = codeguards_mcp::guards::run_guard_checks(
        manifest_dir,
        &files,
        &contract,
        &catalog,
        &exceptions,
    )
    .expect("SlugRails guard execution failed");

    if !report.violations.is_empty() {
        eprintln!("\n═══════════════════════════════════════════════════════════════");
        eprintln!("  SLUGRAILS DETECTED {} ARCHITECTURAL VIOLATION(S)", report.violations.len());
        eprintln!("═══════════════════════════════════════════════════════════════");
        for (i, v) in report.violations.iter().enumerate() {
            let loc = match v.line {
                Some(l) => format!("{}:{}", v.file.display(), l),
                None => format!("{}", v.file.display()),
            };
            eprintln!(" [{}] {} - [{}]", i + 1, loc, v.guard_id);
            eprintln!("     Message: {}", v.message);
            if let Some(ref fix) = v.fix_suggestion {
                eprintln!("     Remediation: {fix}");
            }
        }
        eprintln!("═══════════════════════════════════════════════════════════════\n");
        panic!(
            "SlugRails architecture check failed with {} violation(s). Run 'slugrails check' or add exception.",
            report.violations.len()
        );
    }
}
"#;

/// Writes `tests/slugrails.rs` to the project root.
pub fn run_scaffold_tests(args: impl Iterator<Item = String>) -> ExitCode {
    let args_vec: Vec<String> = args.collect();
    if crate::cli::args::has_help_flag(&args_vec) {
        println!("Usage: slugrails scaffold-tests [--root <path>]\n\nGenerates tests/slugrails.rs integration test harness for native cargo test enforcement.");
        return ExitCode::SUCCESS;
    }
    let root = extract_root(&args_vec);

    match scaffold_tests_harness(&root) {
        Ok(path) => {
            println!("Successfully scaffolded SlugRails harness: {}", path.display());
            println!("Run 'cargo test --test slugrails' to execute architectural enforcement.");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("Failed to scaffold test harness: {e}");
            ExitCode::from(1)
        }
    }
}

/// Generates tests/slugrails.rs in the specified project directory.
pub fn scaffold_tests_harness(root: &Path) -> std::io::Result<std::path::PathBuf> {
    let tests_dir = root.join("tests");
    if !tests_dir.exists() {
        fs::create_dir_all(&tests_dir)?;
    }
    let target = tests_dir.join("slugrails.rs");
    fs::write(&target, TEST_HARNESS_TEMPLATE)?;
    Ok(target)
}
